{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "EM574, a macrolide with a polycyclic lactone-ether scaffold similar to the query, has an estimated oral bioavailability of only ~2% in humans, based on oral clearance far exceeding hepatic blood flow.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A polyether macrolide analogue showed potentially low absolute oral bioavailability in a healthy adult subject, consistent with poor oral absorption of this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Omadacycline, a structurally unrelated tetracycline, has an absolute oral bioavailability of 34.5% in healthy adults, but its absorption mechanism and scaffold are not transferable to the query's macrolide-like lactone system.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a complex polycyclic lactone-ether resembling macrolide/polyether natural products. The most transferable experimental evidence, from macrolide EM574 (~2% F) and a polyether macrolide (low F), supports low oral bioavailability below the 20% threshold. The only positive evidence (omadacycline 34.5%) comes from a structurally unrelated tetracycline and is outweighed by the more relevant macrolide analogues.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule itself.",
    "The exact structural class of the query is not fully established; analogy to macrolides is based on the lactone-ether framework but not confirmed by a named compound.",
    "The polyether macrolide record (C02) is a single-subject observation and not a population estimate."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C25"],
      "decision_effect": "strengthened",
      "direction": "supportive",
